const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2021 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n:host {\n  white-space: normal;\n  display: inline-block;\n}\n\n.icon-button {\n  border: none;\n  margin-right: 2px;\n  margin-top: 4px;\n  display: inline-flex;\n  align-items: center;\n  color: inherit;\n  font-size: inherit;\n  font-family: inherit;\n  background-color: inherit;\n}\n\n.icon-button.with-click-handler {\n  padding: 0 4px;\n}\n\n.icon-button.with-click-handler:hover {\n  background-color: var(--sys-color-state-hover-on-subtle);\n}\n\n.icon-button.icon-button.with-click-handler:active {\n  background-color: var(--color-background-elevation-1);\n}\n\n.icon-button:focus-visible {\n  background-color: var(--sys-color-state-hover-on-subtle);\n}\n\n.icon-button-title {\n  margin-left: 0.5ex;\n}\n\n.compact .icon-button-title {\n  display: none;\n}\n\n.status-icon {\n  margin-left: 1ex;\n}\n\n.status-icon:first-child {\n  margin-left: inherit;\n}\n\n@media (forced-colors: active) {\n  .icon-button {\n    forced-color-adjust: none;\n    background-color: ButtonFace;\n  }\n\n  .icon-button:focus-visible,\n  .icon-button.with-click-handler:hover {\n    background-color: Highlight;\n    color: HighlightText;\n\n    --icon-color: HighlightText;\n  }\n}\n\n/*# sourceURL=iconButton.css */\n");export default styles;